1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
8	
9	/**
10	 * The single duplicate check for create-owner, responding 409 via
11	 * {@link DuplicateOwnerException} for either kind of duplicate:
12	 *
13	 * <ul>
14	 * <li><b>Household duplicate</b> — an existing owner shares the request's deterministic
15	 * {@code householdId} (same last name and postcode, see {@link OwnerHouseholds}). Rejected
16	 * unless the request opts in with {@code sharesHousehold}, which declares it a household member
17	 * and bypasses this block.</li>
18	 * <li><b>Identity duplicate</b> — an existing owner has the same derived {@code identityKey}
19	 * (telephone, email and household, see {@link OwnerIdentities}); this always rejects, so even a
20	 * declared member cannot be an exact resubmission of an existing owner.</li>
21	 * </ul>
22	 *
23	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} so the request
24	 * telephone is already E.164 and its email lower-cased. The household component here matches the
25	 * {@code householdId} that {@link AssignOwnerHousehold} later stores on the owner.
26	 */
27	public class RequireUniqueIdentity {
28	
29	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
30	            throws DuplicateOwnerException {
31	        String householdId = OwnerHouseholds.id(request.getLastName(), request.getPostcode());
32	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
33	        boolean checkHousehold = !sharesHousehold && hasText(request.getPostcode());
34	        String identityKey = OwnerIdentities.key(request.getTelephone(), request.getEmail(), householdId);
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (checkHousehold && householdId.equals(OwnerHouseholds.of(existing))) {
37	                throw new DuplicateOwnerException(householdId);
38	            }
39	            if (identityKey.equals(OwnerIdentities.of(existing))) {
40	                throw new DuplicateOwnerException(identityKey);
41	            }
42	        }
43	    }
44	
45	    private static boolean hasText(String value) {
46	        return value != null && !value.isBlank();
47	    }
48	}
