5	/**
6	 * Shared owner identity for the create-owner pipeline: derives the single canonical
7	 * {@code identityKey} that consolidates all duplicate detection.
8	 *
9	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
10	 * with telephone canonicalized to E.164 (see {@link OwnerTelephones}) and email lower-cased
11	 * (see {@link OwnerEmails}); a missing component contributes an empty string. The
12	 * {@code householdId} is the deterministic (last name, postcode) household key (see
13	 * {@link OwnerHouseholds}). Two owners share this key only when they are the same person in the
14	 * same household — {@link RequireUniqueIdentity} uses it to reject an exact resubmission even of
15	 * a declared household member.
16	 */
17	public final class OwnerIdentities {
18	
19	    private OwnerIdentities() {
20	    }
21	
22	    /**
23	     * Canonical identity key for the given components. {@code telephone} is normalized to
24	     * E.164 and {@code email} lower-cased before assembly; any {@code null} component
25	     * contributes an empty string.
26	     */
27	    public static String key(String telephone, String email, String householdId) {
28	        return part(OwnerTelephones.toE164(telephone)) + "|" + part(OwnerEmails.normalize(email))
29	                + "|" + part(householdId);
30	    }
31	
32	    /** Canonical {@link #key(String, String, String)} for an existing owner's stored fields. */
33	    public static String of(Owner owner) {
34	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
35	    }
36	
37	    private static String part(String value) {
38	        return value == null ? "" : value;
39	    }
40	}
