8	/**
9	 * Shared household identity for the create-owner pipeline: derives the deterministic
10	 * {@code householdId} from an owner's last name and postcode, so every owner with the same
11	 * last name and postcode resolves to the same value automatically — without any owner having
12	 * to opt in.
13	 *
14	 * <p>Two owners belong to the same household exactly when their last names match
15	 * case-insensitively (with collapsed whitespace) and their postcodes are equal.
16	 */
17	final class OwnerHouseholds {
18	
19	    private OwnerHouseholds() {
20	    }
21	
22	    /**
23	     * Deterministic household identifier for {@code lastName} + {@code postcode}: the first 12
24	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Every owner in
25	     * the same household resolves to the same value regardless of when they are created.
26	     */
27	    static String id(String lastName, String postcode) {
28	        String key = normalizeLastName(lastName) + "|" + (postcode == null ? "" : postcode);
29	        return Sha256.hex(key).substring(0, 12);
30	    }
31	
32	    /** Deterministic household id for an existing owner's stored last name and postcode. */
33	    static String of(Owner owner) {
34	        return id(owner.getLastName(), owner.getPostcode());
35	    }
36	
37	    /** Trim, collapse internal whitespace runs to a single space, and lower-case. */
38	    private static String normalizeLastName(String value) {
39	        if (value == null) {
40	            return "";
41	        }
42	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
43	    }
44	}
